class Solution:
    def isPerfectSquare(self, num: int) -> bool:
        lo, hi = 1, num                    # the root, if it exists, lies in [1, num]
        while lo <= hi:                    # range halves each step: O(log num)
            mid = (lo + hi) // 2
            sq = mid * mid
            if sq == num:
                return True
            if sq < num:
                lo = mid + 1               # root must be larger
            else:
                hi = mid - 1               # root must be smaller
        return False

